window.AC_OWN = [{"id": "p_breakout", "name": "Breakout Liemyo", "code": "//@version=6\n// ═══════════════════════════════════════════════════════════════════════\n//  BREAKOUT LIEMYO\n//  • Mode \"Breakout 4H\": searah tren harian + tembus rentang 20 bar, keluar di\n//    SL 3 ATR atau saat garis trailing berbalik. Diuji di BTCUSDT 4h saja.\n//  • Mode \"Klasik\": BUY / SELL tiap garis trailing ditembus, dengan SL + TP\n//  • Mode \"Fraszov 5M\": top-down ala @fraszov (gold). 4H arah (HH/HL),\n//    1H trend, entry 5M dari 5 setup: A false break high/low 1H sebelumnya,\n//    B sweep high/low kemarin, C breakout + retest candle 15M pertama London,\n//    D pullback 50% candle 1H kuat, E sweep likuiditas + patah struktur 5M.\n//    Belum di-backtest.\n//  • Sinyal hanya muncul saat candle tutup (tanpa repaint)\n//  • Dua zona tipis di swing terakhir tiap sinyal, berhenti saat ditembus\n//  • Segitiga kecil = RSI keluar dari jenuh beli / jenuh jual\n//  • Panel skor 0–5 dari 7 faktor: HTF, Trend, RSI, MACD, ROC, %B, Volume\n// ═══════════════════════════════════════════════════════════════════════\nindicator(\"Breakout Liemyo\", shorttitle = \"Breakout Liemyo\", overlay = true, behind_chart = false, max_boxes_count = 100, max_labels_count = 300, max_lines_count = 50)\n\n// ─────────────── INPUT ───────────────\nstring G1 = \"1. Sinyal Breakout\"\nint   atrLen    = input.int(14, \"Panjang ATR\", minval = 1, group = G1)\nfloat atrMult   = input.float(3.0, \"Jarak trailing (x ATR)\", minval = 0.5, step = 0.1, group = G1)\nstring ruleMode = input.string(\"Fraszov 5M\", \"Aturan sinyal\", options = [\"Fraszov 5M\", \"Breakout 4H\", \"Klasik\"], group = G1, tooltip = \"Fraszov 5M: top-down 4H/1H/5M dengan 5 setup (grup 6), untuk chart 5m, belum di-backtest. Breakout 4H: aturan hasil backtest BTCUSDT 4h. Klasik: aturan versi pertama, tanpa keunggulan stabil di backtest.\")\nint   donLen    = input.int(20, \"Rentang breakout (bar)\", minval = 2, group = G1)\nbool  useFilter = input.bool(true, \"Saring dengan skor panel\", group = G1, tooltip = \"BUY hanya jika skor >= batas, SELL hanya jika skor <= 5 - batas\")\nfloat minScore  = input.float(2.5, \"Batas skor\", minval = 2.5, maxval = 5.0, step = 0.25, group = G1)\n\nstring G2 = \"2. Stop Loss & Take Profit\"\nfloat slMultB = input.float(3.0, \"SL Breakout 4H (x ATR)\", minval = 0.1, step = 0.1, group = G2)\nfloat slMult = input.float(2.0, \"SL Klasik (x ATR)\", minval = 0.1, step = 0.1, group = G2)\nbool  showTpB = input.bool(false, \"Tampilkan TP di Breakout 4H\", group = G2, tooltip = \"Aturan yang diuji tidak memakai TP. Posisi ditutup oleh SL atau saat garis trailing berbalik.\")\nfloat tp1R   = input.float(1.0, \"TP1 (kelipatan risiko R)\", minval = 0.1, step = 0.1, group = G2)\nfloat tp2R   = input.float(2.0, \"TP2 (kelipatan risiko R)\", minval = 0.2, step = 0.1, group = G2)\nbool  showLv = input.bool(true, \"Tampilkan garis SL / TP\", group = G2)\nbool  showEn = input.bool(false, \"Tampilkan garis Entry\", group = G2)\nint   lblGap = input.int(8, \"Ujung garis & label dari bar terakhir (bar)\", minval = 0, maxval = 100, group = G2)\n\nstring G3 = \"3. Zona Swing\"\nbool  showZone = input.bool(true, \"Tampilkan zona\", group = G3)\nint   swingLb  = input.int(20, \"Lookback swing (bar)\", minval = 2, group = G3)\nint   maxZones = input.int(8, \"Jumlah zona maksimal\", minval = 2, maxval = 40, group = G3)\n\nstring G4 = \"4. Panel Skor\"\nbool   showTbl = input.bool(true, \"Tampilkan panel\", group = G4)\nstring tblPos  = input.string(\"Otomatis\", \"Posisi\", options = [\"Otomatis\", \"Kanan atas\", \"Kanan bawah\", \"Kiri atas\", \"Kiri bawah\", \"Tengah atas\"], group = G4, tooltip = \"Otomatis: panel di kanan bawah saat harga di separuh atas rentang 150 bar, dan di kanan atas saat harga di separuh bawah\")\nstring tblSize = input.string(\"Kecil\", \"Ukuran teks\", options = [\"Mungil\", \"Kecil\", \"Normal\"], group = G4)\nstring htfTf   = input.timeframe(\"D\", \"Timeframe HTF Bias\", group = G4)\n\nstring G5 = \"5. Garis & Faktor\"\nint  fastLen = input.int(21, \"EMA cepat\", minval = 1, group = G5)\nint  slowLen = input.int(55, \"EMA lambat\", minval = 2, group = G5)\nint  rsiLen  = input.int(14, \"Panjang RSI\", minval = 2, group = G5)\nint  rocLen  = input.int(10, \"Panjang ROC\", minval = 1, group = G5)\nint  bbLen   = input.int(20, \"Panjang Bollinger\", minval = 2, group = G5)\nint  volLen  = input.int(14, \"Panjang Volume\", minval = 2, group = G5)\nbool showTri = input.bool(true, \"Segitiga RSI jenuh\", group = G5)\n\nstring G6 = \"6. Fraszov 5M\"\nint    fPiv      = input.int(3, \"Pivot struktur 4H / 1H (bar)\", minval = 1, group = G6, tooltip = \"4H HH+HL = hanya BUY, LH+LL = hanya SELL, campur = tidak trading\")\nstring fAlign    = input.string(\"Tidak berlawanan\", \"Syarat trend 1H\", options = [\"Tidak berlawanan\", \"Searah 4H\"], group = G6)\nbool   fUseA     = input.bool(true, \"A. False break high/low 1H sebelumnya\", group = G6)\nbool   fUseB     = input.bool(true, \"B. Sweep high/low kemarin\", group = G6)\nbool   fUseC     = input.bool(true, \"C. Breakout + retest candle 15M pertama London\", group = G6)\nbool   fUseD     = input.bool(true, \"D. Pullback 50% candle 1H kuat\", group = G6)\nbool   fUseE     = input.bool(true, \"E. Sweep likuiditas + patah struktur 5M\", group = G6)\nint    fConfBars = input.int(6, \"Batas tunggu konfirmasi (bar)\", minval = 1, group = G6)\nfloat  fBodyK    = input.float(1.0, \"Candle 1H kuat: body >= x ATR 1H\", minval = 0.1, step = 0.1, group = G6)\nint    fSwing    = input.int(3, \"Pivot swing 5M (bar)\", minval = 1, group = G6)\nstring fLonOpen  = input.session(\"0800-0815\", \"Candle 15M pertama London\", group = G6)\nstring fLonWin   = input.session(\"0815-1200\", \"Jendela setup London\", group = G6)\nfloat  fSlBuf    = input.float(0.2, \"Buffer SL di luar invalidasi (x ATR)\", minval = 0.0, step = 0.05, group = G6)\nfloat  fSlMin    = input.float(0.5, \"SL minimal (x ATR)\", minval = 0.1, step = 0.1, group = G6)\nfloat  fSlMax    = input.float(4.0, \"SL maksimal (x ATR), lebih jauh = lewati\", minval = 0.5, step = 0.1, group = G6)\nbool   fShowLv   = input.bool(true, \"Tampilkan level 1H, kemarin, London, 50%\", group = G6)\n\n// ─────────────── WARNA ───────────────\ncolor cBuy      = #00BCD4\ncolor cSell     = #FF5252\ncolor cStrBuy   = #00897B\ncolor cSoftBuy  = #26A69A\ncolor cHold     = #5D6D7E\ncolor cSoftSell = #D9534F\ncolor cStrSell  = #B71C1C\ncolor cPanel    = #2A2E39\ncolor cText     = #D1D4DC\n\n// ─────────────── TRAILING + GARIS ───────────────\nfloat atrV = ta.atr(atrLen)\n[stLine, stDir] = ta.supertrend(atrMult, atrLen)\nbool stUp = stDir < 0\n\nfloat emaFast = ta.ema(close, fastLen)\nfloat emaSlow = ta.ema(close, slowLen)\n\n// ─────────────── 7 FAKTOR (-2 sampai +2) ───────────────\n// HTF: memakai bar HTF yang sudah tutup agar tidak repaint\n[htfE50, htfE50Prev, htfE200] = request.security(syminfo.tickerid, htfTf, [ta.ema(close, 50)[1], ta.ema(close, 50)[2], ta.ema(close, 200)[1]], lookahead = barmerge.lookahead_on)\nint htfRaw = na(htfE50) ? 0 : (close > htfE50 ? 1 : -1) + (htfE50 > htfE50Prev ? 1 : -1) + (na(htfE200) ? 0 : htfE50 > htfE200 ? 1 : -1)\nint sHtf = htfRaw >= 3 ? 2 : htfRaw >= 1 ? 1 : htfRaw <= -3 ? -2 : htfRaw <= -1 ? -1 : 0\n\n// Trend: arah EMA + kekuatan ADX\n[diP, diM, adxV] = ta.dmi(14, 14)\nint  trendDir = emaFast > emaSlow ? 1 : -1\nbool trendOk  = (close > emaFast) == (emaFast > emaSlow)\nint  sTrend   = adxV < 18 or not trendOk ? 0 : adxV >= 25 ? 2 * trendDir : trendDir\n\n// RSI\nfloat rsiV = ta.rsi(close, rsiLen)\nint sRsi = rsiV >= 60 ? 2 : rsiV >= 55 ? 1 : rsiV <= 40 ? -2 : rsiV <= 45 ? -1 : 0\n\n// MACD: histogram dan arahnya\n[macdL, macdS, macdH] = ta.macd(close, 12, 26, 9)\nbool macdFlat = math.abs(macdH) < 0.02 * atrV\nint sMacd = macdFlat ? 0 : macdH > 0 ? (macdH > macdH[1] ? 2 : 1) : macdH < 0 ? (macdH < macdH[1] ? -2 : -1) : 0\n\n// ROC: perubahan harga dalam satuan ATR\nfloat rocAtr = atrV > 0 ? (close - close[rocLen]) / atrV : 0.0\nint sRoc = rocAtr >= 2.0 ? 2 : rocAtr >= 0.75 ? 1 : rocAtr <= -2.0 ? -2 : rocAtr <= -0.75 ? -1 : 0\n\n// Bollinger %B\n[bbMid, bbUp, bbLo] = ta.bb(close, bbLen, 2.0)\nfloat pctB = bbUp > bbLo ? (close - bbLo) / (bbUp - bbLo) : 0.5\nint sBb = pctB >= 0.85 ? 2 : pctB >= 0.6 ? 1 : pctB <= 0.15 ? -2 : pctB <= 0.4 ? -1 : 0\n\n// Volume: porsi volume naik terhadap total\nfloat volV   = nz(volume)\nfloat volSum = math.sum(volV, volLen)\nfloat upSum  = math.sum(close >= open ? volV : 0.0, volLen)\nfloat upPct  = volSum > 0 ? upSum / volSum : 0.5\nint sVol = upPct >= 0.65 ? 2 : upPct >= 0.55 ? 1 : upPct <= 0.35 ? -2 : upPct <= 0.45 ? -1 : 0\n\n// Skor 0–5 (2.5 = netral)\nfloat scoreAvg = (sHtf + sTrend + sRsi + sMacd + sRoc + sBb + sVol) / 7.0\nfloat score    = (scoreAvg + 2.0) * 1.25\nint   sVerdict = score >= 3.5 ? 2 : score > 2.75 ? 1 : score <= 1.5 ? -2 : score < 2.25 ? -1 : 0\n\n// ─────────────── FRASZOV 5M ───────────────\n// Struktur: HH+HL = 1, LH+LL = -1, campur = 0. Memakai bar HTF yang sudah tutup.\nf_structDir(int len) =>\n    float ph = ta.pivothigh(high, len, len)\n    float pl = ta.pivotlow(low, len, len)\n    var float hA = na\n    var float hB = na\n    var float lA = na\n    var float lB = na\n    if not na(ph)\n        hB := hA\n        hA := ph\n    if not na(pl)\n        lB := lA\n        lA := pl\n    int d = na(hB) or na(lB) ? 0 : hA > hB and lA > lB ? 1 : hA < hB and lA < lB ? -1 : 0\n    d\n\nf_prevDir(int len) =>\n    int d = f_structDir(len)\n    d[1]\n\nint dir4h = nz(request.security(syminfo.tickerid, \"240\", f_prevDir(fPiv), lookahead = barmerge.lookahead_on))\nint dir1h = nz(request.security(syminfo.tickerid, \"60\", f_prevDir(fPiv), lookahead = barmerge.lookahead_on))\nbool fBiasUp = dir4h == 1 and (fAlign == \"Searah 4H\" ? dir1h == 1 : dir1h != -1)\nbool fBiasDn = dir4h == -1 and (fAlign == \"Searah 4H\" ? dir1h == -1 : dir1h != 1)\n\n[pH1, pL1, pO1, pC1, pA1] = request.security(syminfo.tickerid, \"60\", [high[1], low[1], open[1], close[1], ta.atr(14)[1]], lookahead = barmerge.lookahead_on)\n[yH, yL] = request.security(syminfo.tickerid, \"D\", [high[1], low[1]], lookahead = barmerge.lookahead_on)\n\n// A & B: tembus level lalu close kembali ke dalam, lalu candle berikut close melewati ujung candle sweep\nf_sweep(float lvlH, float lvlL, int maxBars) =>\n    var int   sBar  = na\n    var float sExt  = na\n    var float sTrig = na\n    var int   bBar  = na\n    var float bExt  = na\n    var float bTrig = na\n    int   sig  = 0\n    float stop = na\n    if not na(sBar) and bar_index > sBar\n        if high > sExt\n            sBar := na\n        else if close < sTrig\n            sig  := -1\n            stop := sExt\n            sBar := na\n        else if bar_index - sBar >= maxBars\n            sBar := na\n    if not na(bBar) and bar_index > bBar\n        if low < bExt\n            bBar := na\n        else if close > bTrig\n            sig  := 1\n            stop := bExt\n            bBar := na\n        else if bar_index - bBar >= maxBars\n            bBar := na\n    if not na(lvlH) and high > lvlH and close < lvlH\n        sBar  := bar_index\n        sExt  := high\n        sTrig := low\n    if not na(lvlL) and low < lvlL and close > lvlL\n        bBar  := bar_index\n        bExt  := low\n        bTrig := high\n    [sig, stop]\n\n[sigA, stopA] = f_sweep(pH1, pL1, fConfBars)\n[sigB, stopB] = f_sweep(yH, yL, fConfBars)\n\n// C: rentang candle 15M pertama London, close di luar, retest bertahan, candle berikut searah\nbool inOR  = not na(time(timeframe.period, fLonOpen, \"Europe/London\"))\nbool inWin = not na(time(timeframe.period, fLonWin, \"Europe/London\"))\nvar float orH     = na\nvar float orL     = na\nvar int   orStage = 0\nvar int   rtBar   = na\nvar float rtHi    = na\nvar float rtLo    = na\nif inOR and not inOR[1]\n    orH     := high\n    orL     := low\n    orStage := 0\n    rtBar   := na\nelse if inOR\n    orH := math.max(orH, high)\n    orL := math.min(orL, low)\nint   sigC  = 0\nfloat stopC = na\nif inWin and not inOR and not na(orH)\n    if orStage == 0\n        if close > orH\n            orStage := 1\n        else if close < orL\n            orStage := -1\n    else if orStage == 1\n        if not na(rtBar) and bar_index > rtBar\n            if close > rtHi\n                sigC    := 1\n                stopC   := rtLo\n                orStage := 2\n            rtBar := na\n        if orStage == 1\n            if close < orH\n                orStage := 0\n            else if low <= orH\n                rtBar := bar_index\n                rtHi  := high\n                rtLo  := low\n    else if orStage == -1\n        if not na(rtBar) and bar_index > rtBar\n            if close < rtLo\n                sigC    := -1\n                stopC   := rtHi\n                orStage := 2\n            rtBar := na\n        if orStage == -1\n            if close > orL\n                orStage := 0\n            else if high >= orL\n                rtBar := bar_index\n                rtHi  := high\n                rtLo  := low\n\n// D: candle 1H sebelumnya kuat, harga kembali ke 50%-nya dan 5M bertahan\nbool  newHour    = ta.change(time(\"60\")) != 0\nbool  strongBull = not na(pA1) and pC1 - pO1 >= fBodyK * pA1\nbool  strongBear = not na(pA1) and pO1 - pC1 >= fBodyK * pA1\nfloat mid1       = (pH1 + pL1) / 2.0\nvar bool dUsed = false\nif newHour\n    dUsed := false\nint   sigD  = 0\nfloat stopD = na\nif not dUsed and strongBull and low <= mid1 and close > mid1 and close > open\n    sigD  := 1\n    stopD := math.min(low, low[1])\n    dUsed := true\nelse if not dUsed and strongBear and high >= mid1 and close < mid1 and close < open\n    sigD  := -1\n    stopD := math.max(high, high[1])\n    dUsed := true\n\n// E: sweep swing high/low 5M → close kuat melewati swing lawan → pullback tertahan + rejection\nfloat swPH = ta.pivothigh(high, fSwing, fSwing)\nfloat swPL = ta.pivotlow(low, fSwing, fSwing)\nvar float lastPH = na\nvar float lastPL = na\nif not na(swPH)\n    lastPH := swPH\nif not na(swPL)\n    lastPL := swPL\nint   eWait = fConfBars * 4\nvar int   eS    = 0\nvar int   eSBar = na\nvar float eSExt = na\nvar float eSLvl = na\nvar float eSPb  = na\nvar int   eB    = 0\nvar int   eBBar = na\nvar float eBExt = na\nvar float eBLvl = na\nvar float eBPb  = na\nint   sigE  = 0\nfloat stopE = na\n// sisi SELL\nif eS == 2\n    eSPb := math.max(eSPb, high)\n    if close > eSLvl or bar_index - eSBar > eWait\n        eS := 0\n    else if high >= eSLvl - 0.25 * atrV and close < open\n        sigE  := -1\n        stopE := eSPb\n        eS    := 0\nelse if eS == 1\n    if high > eSExt\n        eSExt := high\n        eSBar := bar_index\n    if not na(lastPL) and close < lastPL and open - close >= 0.5 * atrV\n        eS    := 2\n        eSLvl := lastPL\n        eSBar := bar_index\n        eSPb  := high\n    else if bar_index - eSBar > eWait\n        eS := 0\nif eS == 0 and sigE == 0 and not na(lastPH) and high > lastPH\n    eS    := 1\n    eSExt := high\n    eSBar := bar_index\n// sisi BUY\nif eB == 2\n    eBPb := math.min(eBPb, low)\n    if close < eBLvl or bar_index - eBBar > eWait\n        eB := 0\n    else if low <= eBLvl + 0.25 * atrV and close > open and sigE == 0\n        sigE  := 1\n        stopE := eBPb\n        eB    := 0\nelse if eB == 1\n    if low < eBExt\n        eBExt := low\n        eBBar := bar_index\n    if not na(lastPH) and close > lastPH and close - open >= 0.5 * atrV\n        eB    := 2\n        eBLvl := lastPH\n        eBBar := bar_index\n        eBPb  := low\n    else if bar_index - eBBar > eWait\n        eB := 0\nif eB == 0 and not na(lastPL) and low < lastPL\n    eB    := 1\n    eBExt := low\n    eBBar := bar_index\n\n// Pilih setup pertama yang searah bias 4H/1H\nint    fPick = 0\nfloat  fStop = na\nstring fName = \"\"\nf_ok(int s) =>\n    (s == 1 and fBiasUp) or (s == -1 and fBiasDn)\nif fUseA and f_ok(sigA)\n    fPick := sigA\n    fStop := stopA\n    fName := \"A FB 1H\"\nelse if fUseB and f_ok(sigB)\n    fPick := sigB\n    fStop := stopB\n    fName := \"B Kemarin\"\nelse if fUseC and f_ok(sigC)\n    fPick := sigC\n    fStop := stopC\n    fName := \"C London\"\nelse if fUseD and f_ok(sigD)\n    fPick := sigD\n    fStop := stopD\n    fName := \"D 50% 1H\"\nelse if fUseE and f_ok(sigE)\n    fPick := sigE\n    fStop := stopE\n    fName := \"E Sweep\"\nfloat fRisk = na\nif fPick != 0\n    fRisk := math.max(math.abs(close - (fStop - fPick * fSlBuf * atrV)), fSlMin * atrV)\n    if fRisk > fSlMax * atrV\n        fPick := 0\n\n// ─────────────── POSISI & SINYAL ───────────────\nbool  isFras     = ruleMode == \"Fraszov 5M\"\nbool  isBreakout = ruleMode == \"Breakout 4H\"\nfloat slUse      = isBreakout ? slMultB : slMult\n\nvar int   lastSig = 0\nvar bool  legDone = false\nvar bool  tOpen   = false\nvar int   tDir    = 0\nvar int   tBar    = na\nvar float enP     = na\nvar float slP     = na\nvar float tp1P    = na\nvar float tp2P    = na\nvar bool  hit1    = false\nvar bool  hit2    = false\nvar bool  hitSl   = false\nvar string tName  = \"\"\n\nbool newTp1  = false\nbool newTp2  = false\nbool newSl   = false\nbool exitSig = false\n\n// 1. Kelola posisi yang terbuka. SL didahulukan bila SL dan TP tersentuh di candle yang sama.\nif tOpen and bar_index > tBar\n    bool slTouch  = tDir == 1 ? low <= slP : high >= slP\n    bool tp1Touch = tDir == 1 ? high >= tp1P : low <= tp1P\n    bool tp2Touch = tDir == 1 ? high >= tp2P : low <= tp2P\n    if isBreakout\n        if slTouch\n            hitSl := true\n            newSl := true\n            tOpen := false\n            exitSig := true\n        else\n            if tp1Touch and not hit1\n                hit1 := true\n                newTp1 := true\n            if tp2Touch and not hit2\n                hit2 := true\n                newTp2 := true\n    else\n        if slTouch and not hit1\n            hitSl := true\n            newSl := true\n        else\n            if tp1Touch and not hit1\n                hit1 := true\n                newTp1 := true\n            if tp2Touch\n                hit2 := true\n                newTp2 := true\n            if slTouch and not hit2\n                hitSl := true\n                newSl := true\n        if hitSl or hit2\n            tOpen := false\n\n// 2. Breakout 4H: garis trailing berbalik menutup posisi dan membuka leg baru.\nif stDir != stDir[1]\n    legDone := false\nif isBreakout and tOpen and barstate.isconfirmed and (tDir == 1 ? not stUp : stUp)\n    tOpen := false\n    exitSig := true\n\n// 3. Sinyal baru\nbool regimeUp = not na(htfE50) and not na(htfE200) and close > htfE50 and htfE50 > htfE200\nbool regimeDn = not na(htfE50) and not na(htfE200) and close < htfE50 and htfE50 < htfE200\nfloat donHi = ta.highest(high, donLen)[1]\nfloat donLo = ta.lowest(low, donLen)[1]\nbool scoreUp = not useFilter or score >= minScore\nbool scoreDn = not useFilter or score <= 5.0 - minScore\n\nbool buySig  = false\nbool sellSig = false\nif barstate.isconfirmed\n    if isBreakout\n        if not tOpen and not legDone\n            buySig  := stUp and regimeUp and close > donHi and scoreUp\n            sellSig := not stUp and regimeDn and close < donLo and scoreDn\n    else if isFras\n        if not tOpen\n            buySig  := fPick == 1\n            sellSig := fPick == -1\n    else\n        buySig  := stUp and lastSig != 1 and scoreUp\n        sellSig := not stUp and lastSig != -1 and scoreDn\n\nif buySig or sellSig\n    lastSig := buySig ? 1 : -1\n    legDone := true\n    tOpen := true\n    tDir  := buySig ? 1 : -1\n    tBar  := bar_index\n    enP   := close\n    float risk = isFras ? fRisk : slUse * atrV\n    tName := isFras ? fName : \"\"\n    slP   := close - tDir * risk\n    tp1P  := close + tDir * tp1R * risk\n    tp2P  := close + tDir * tp2R * risk\n    hit1  := false\n    hit2  := false\n    hitSl := false\n\nbool triUp = showTri and barstate.isconfirmed and ta.crossover(rsiV, 30)\nbool triDn = showTri and barstate.isconfirmed and ta.crossunder(rsiV, 70)\n\n// ─────────────── ZONA SWING ───────────────\ntype Zone\n    box  b\n    int  side\n    bool active = true\n\nvar array<Zone> zones = array.new<Zone>()\n\nf_addZone(float top, float bot, int side, int leftBar) =>\n    color c = side == 1 ? cBuy : cSell\n    box b = box.new(leftBar, top, bar_index + 10, bot, border_color = color.new(c, 35), bgcolor = color.new(c, 80))\n    zones.push(Zone.new(b, side, true))\n    if zones.size() > maxZones\n        Zone old = zones.shift()\n        old.b.delete()\n\nfloat swLow  = ta.lowest(low, swingLb)\nfloat swHigh = ta.highest(high, swingLb)\nint   swLowX  = bar_index + ta.lowestbars(low, swingLb)\nint   swHighX = bar_index + ta.highestbars(high, swingLb)\n\nif showZone\n    for z in zones\n        if z.active\n            bool broken = z.side == 1 ? close < z.b.get_bottom() : close > z.b.get_top()\n            if broken\n                z.active := false\n                z.b.set_right(bar_index)\n            else\n                z.b.set_right(bar_index + 10)\n    if buySig\n        f_addZone(swLow + 0.4 * atrV, swLow, 1, swLowX)\n        f_addZone(swLow + 1.2 * atrV, swLow + 0.8 * atrV, 1, swLowX)\n    if sellSig\n        f_addZone(swHigh, swHigh - 0.4 * atrV, -1, swHighX)\n        f_addZone(swHigh - 0.8 * atrV, swHigh - 1.2 * atrV, -1, swHighX)\n\n// ─────────────── PLOT ───────────────\nplot(not isFras and stUp ? stLine : na, \"Trailing Naik\", color = cBuy, linewidth = 2, style = plot.style_linebr)\nplot(not isFras and not stUp ? stLine : na, \"Trailing Turun\", color = cSell, linewidth = 2, style = plot.style_linebr)\n\nbool fLv = isFras and fShowLv\nplot(fLv ? pH1 : na, \"High 1H sebelumnya\", color = color.new(#FFB74D, 35), style = plot.style_stepline)\nplot(fLv ? pL1 : na, \"Low 1H sebelumnya\", color = color.new(#FFB74D, 35), style = plot.style_stepline)\nplot(fLv ? yH : na, \"High kemarin\", color = color.new(#BA68C8, 20), linewidth = 2, style = plot.style_stepline)\nplot(fLv ? yL : na, \"Low kemarin\", color = color.new(#BA68C8, 20), linewidth = 2, style = plot.style_stepline)\nplot(fLv and (inOR or inWin) ? orH : na, \"London 15M high\", color = #FFD54F, linewidth = 2, style = plot.style_linebr)\nplot(fLv and (inOR or inWin) ? orL : na, \"London 15M low\", color = #FFD54F, linewidth = 2, style = plot.style_linebr)\nplot(fLv and (strongBull or strongBear) ? mid1 : na, \"50% candle 1H kuat\", color = color.new(#90CAF9, 10), style = plot.style_linebr)\nbgcolor(fLv and inOR ? color.new(#FFD54F, 88) : na, title = \"Candle 15M pertama London\")\npFast = plot(emaFast, \"EMA Cepat\", color = emaFast > emaSlow ? color.new(cBuy, 15) : color.new(cSell, 15), linewidth = 2)\npSlow = plot(emaSlow, \"EMA Lambat\", color = color.new(#9598A1, 45), linewidth = 1)\nfill(pFast, pSlow, color = emaFast > emaSlow ? color.new(cBuy, 88) : color.new(cSell, 88), title = \"Isi EMA\")\n\nplotshape(buySig and not isFras, \"BUY\", shape.labelup, location.belowbar, cBuy, text = \"BUY\", textcolor = color.white, size = size.small)\nplotshape(sellSig and not isFras, \"SELL\", shape.labeldown, location.abovebar, cSell, text = \"SELL\", textcolor = color.white, size = size.small)\nif isFras and (buySig or sellSig)\n    label.new(bar_index, buySig ? low : high, (buySig ? \"BUY\\n\" : \"SELL\\n\") + tName, yloc = buySig ? yloc.belowbar : yloc.abovebar, style = buySig ? label.style_label_up : label.style_label_down, color = buySig ? cBuy : cSell, textcolor = color.white, size = size.small)\nplotshape(isFras and (newSl or newTp2), \"Posisi selesai\", shape.xcross, location.abovebar, #9598A1, size = size.tiny)\nplotshape(exitSig and isBreakout, \"EXIT\", shape.xcross, location.abovebar, #9598A1, text = \"EXIT\", textcolor = #9598A1, size = size.tiny)\nplotshape(triUp, \"RSI keluar jenuh jual\", shape.triangleup, location.belowbar, cBuy, size = size.tiny)\nplotshape(triDn, \"RSI keluar jenuh beli\", shape.triangledown, location.abovebar, cSell, size = size.tiny)\n\n// ─────────────── GARIS SL / TP DI KANAN ───────────────\nstring F = format.mintick\n\nf_newLine(color c) =>\n    line.new(na, na, na, na, color = color.new(c, 25), style = line.style_dotted)\n\nf_newLabel(color bg, color c) =>\n    label.new(na, na, \"\", style = label.style_label_right, color = bg, textcolor = c, size = size.small)\n\nvar line  lnSl  = f_newLine(cSell)\nvar line  lnTp1 = f_newLine(cBuy)\nvar line  lnTp2 = f_newLine(cBuy)\nvar line  lnEn  = f_newLine(#9598A1)\nvar label lbSl  = f_newLabel(#4A1F24, cSell)\nvar label lbTp1 = f_newLabel(#0F3F47, cBuy)\nvar label lbTp2 = f_newLabel(#0F3F47, cBuy)\nvar label lbEn  = f_newLabel(#2A2E39, #D1D4DC)\n\nf_level(line l, label b, float p, string t) =>\n    int x = bar_index + lblGap\n    l.set_xy1(tBar, p)\n    l.set_xy2(x, p)\n    b.set_xy(x, p)\n    b.set_text(t)\n\nif barstate.islast and tDir != 0 and showLv\n    f_level(lnSl, lbSl, slP, \"SL \" + str.tostring(slP, F) + (hitSl ? \"  x\" : not tOpen ? \"  selesai\" : \"\"))\n    if not isBreakout or showTpB\n        f_level(lnTp1, lbTp1, tp1P, \"TP1 \" + str.tostring(tp1P, F) + (hit1 ? \"  v\" : \"\"))\n        f_level(lnTp2, lbTp2, tp2P, \"TP2 \" + str.tostring(tp2P, F) + (hit2 ? \"  v\" : \"\"))\n    if showEn\n        f_level(lnEn, lbEn, enP, (tDir == 1 ? \"BUY \" : \"SELL \") + str.tostring(enP, F))\n\n// ─────────────── PANEL ───────────────\nf_txt(int s) =>\n    s >= 2 ? \"STRONG BUY\" : s == 1 ? \"BUY\" : s == 0 ? \"HOLD\" : s == -1 ? \"SELL\" : \"STRONG SELL\"\n\nf_col(int s) =>\n    s >= 2 ? cStrBuy : s == 1 ? cSoftBuy : s == 0 ? cHold : s == -1 ? cSoftSell : cStrSell\n\nstring tSize = tblSize == \"Mungil\" ? size.tiny : tblSize == \"Normal\" ? size.normal : size.small\nstring posA = tblPos == \"Kanan bawah\" ? position.bottom_right : tblPos == \"Kiri atas\" ? position.top_left : tblPos == \"Kiri bawah\" ? position.bottom_left : tblPos == \"Tengah atas\" ? position.top_center : position.top_right\n\nf_newTable(string pos) =>\n    table.new(pos, 2, 13, bgcolor = cPanel, border_color = color.new(#787B86, 50), border_width = 1, frame_color = #787B86, frame_width = 1)\n\nvar table tbA = f_newTable(posA)\nvar table tbB = f_newTable(position.bottom_right)\nfloat rangeMid = (ta.highest(high, 150) + ta.lowest(low, 150)) / 2.0\n\nf_row(table tb, int r, string name, int s) =>\n    table.cell(tb, 0, r, name, text_color = cText, bgcolor = cPanel, text_halign = text.align_left, text_size = tSize)\n    table.cell(tb, 1, r, f_txt(s), text_color = color.white, bgcolor = f_col(s), text_size = tSize)\n\nif barstate.islast and showTbl\n    bool  useB  = tblPos == \"Otomatis\" and close > rangeMid\n    table tb    = useB ? tbB : tbA\n    table other = useB ? tbA : tbB\n    other.clear(0, 0, 1, 12)\n    table.cell(tb, 0, 0, \"BREAKOUT LIEMYO\", text_color = color.white, bgcolor = cPanel, text_size = tSize == size.tiny ? size.small : size.normal)\n    table.cell(tb, 1, 0, str.tostring(score, \"0.0\") + \"/5\", text_color = color.white, bgcolor = f_col(sVerdict), text_size = tSize == size.tiny ? size.small : size.normal)\n    f_row(tb, 1, \"VERDICT\", sVerdict)\n    f_row(tb, 2, \"HTF Bias (\" + htfTf + \")\", sHtf)\n    f_row(tb, 3, \"Trend\", sTrend)\n    f_row(tb, 4, \"Momentum RSI\", sRsi)\n    f_row(tb, 5, \"MACD\", sMacd)\n    f_row(tb, 6, \"ROC\", sRoc)\n    f_row(tb, 7, \"Bands %B\", sBb)\n    f_row(tb, 8, \"Volume\", sVol)\n    table.cell(tb, 0, 9, \"Posisi\", text_color = cText, bgcolor = cPanel, text_halign = text.align_left, text_size = tSize)\n    string posTxt = tOpen ? (tDir == 1 ? \"LONG\" : \"SHORT\") + (tName != \"\" ? \" \" + tName : \"\") : \"FLAT\"\n    table.cell(tb, 1, 9, posTxt, text_color = color.white, bgcolor = tOpen ? (tDir == 1 ? cStrBuy : cStrSell) : cHold, text_size = tSize)\n    table.cell(tb, 0, 10, \"4H Arah\", text_color = cText, bgcolor = cPanel, text_halign = text.align_left, text_size = tSize)\n    table.cell(tb, 1, 10, dir4h == 1 ? \"HH/HL NAIK\" : dir4h == -1 ? \"LH/LL TURUN\" : \"CAMPUR\", text_color = color.white, bgcolor = dir4h == 1 ? cStrBuy : dir4h == -1 ? cStrSell : cHold, text_size = tSize)\n    table.cell(tb, 0, 11, \"1H Trend\", text_color = cText, bgcolor = cPanel, text_halign = text.align_left, text_size = tSize)\n    table.cell(tb, 1, 11, dir1h == 1 ? \"NAIK\" : dir1h == -1 ? \"TURUN\" : \"CAMPUR\", text_color = color.white, bgcolor = dir1h == 1 ? cSoftBuy : dir1h == -1 ? cSoftSell : cHold, text_size = tSize)\n    bool offTf = (isBreakout and timeframe.period != \"240\") or (isFras and timeframe.period != \"5\")\n    string tfTip = isBreakout ? \"Aturan Breakout 4H hanya diuji di timeframe 4h\" : \"Fraszov 5M dibuat untuk chart 5m\"\n    table.cell(tb, 0, 12, syminfo.ticker, text_color = color.new(cText, 30), bgcolor = cPanel, text_halign = text.align_left, text_size = tSize)\n    table.cell(tb, 1, 12, timeframe.period, text_color = offTf ? color.orange : color.new(cText, 30), bgcolor = cPanel, text_size = tSize, tooltip = offTf ? tfTip : \"\")\n\n// ─────────────── ALERT ───────────────\nalertcondition(buySig, \"Breakout Liemyo BUY\", \"BUY {{ticker}} di {{close}} ({{interval}})\")\nalertcondition(sellSig, \"Breakout Liemyo SELL\", \"SELL {{ticker}} di {{close}} ({{interval}})\")\nalertcondition(newTp1, \"Breakout Liemyo TP1\", \"TP1 {{ticker}} tersentuh\")\nalertcondition(newTp2, \"Breakout Liemyo TP2\", \"TP2 {{ticker}} tersentuh\")\nalertcondition(newSl, \"Breakout Liemyo SL\", \"SL {{ticker}} tersentuh\")\nalertcondition(exitSig and isBreakout, \"Breakout Liemyo EXIT\", \"EXIT posisi {{ticker}} di {{close}}\")\n\nif buySig or sellSig\n    string tpTxt = isBreakout and not showTpB ? \"\" : \" | TP1 \" + str.tostring(tp1P, F) + \" | TP2 \" + str.tostring(tp2P, F)\n    alert((buySig ? \"BUY \" : \"SELL \") + syminfo.ticker + (tName != \"\" ? \" [\" + tName + \"]\" : \"\") + \" entry \" + str.tostring(enP, F) + \" | SL \" + str.tostring(slP, F) + tpTxt, alert.freq_once_per_bar_close)\nif exitSig and isBreakout\n    alert(\"EXIT \" + syminfo.ticker + \" di \" + str.tostring(close, F), alert.freq_once_per_bar_close)\n"}];
